// <auto-generated/>
using System;
using System.Collections;
using System.Linq;
using Fanex.Tarus.Customer.Constants;
using Fanex.Tarus.Customer.CreditCustomer.DataAccess;
using Fanex.Tarus.Customer.CreditCustomer.Entities;
using Fanex.Tarus.Customer.Criteria.AutoTransfer;
using Fanex.Tarus.Customer.DataAccess.AutoTransfer;
using Fanex.Tarus.Customer.Entities;
using Fanex.Tarus.Customer.Resources;
using Sunplus.Accounting.Core.Extensions;

public partial class Customer_V2_UpdateTransferTime : RequiredAuthorizationPage
{
    private ICustomerSettingDataAccess customerSettingDataAccess = new CustomerSettingDataAccess();
    private IAutoTransferDatalAccess autoTransferDataAccess = new AutoTransferDatalAccess();

    protected override bool HasPermission()
    {
        return true;
    }

    protected void Page_Load(object sender, EventArgs e)
    {
        try
        {
            UpdateData();
        }
        catch (Exception ex)
        {
            LogExtensions.ExceptionHandler(ex);

            Response.Write("<script type=\"text/javascript\">parent.showAlertMessage('err','" + IBCUtils.Encryption.RemoveSpecialChars(ex.Message) + "',1); parent.afterUpdate(false, 2000);</script>");
        }
    }

    protected override void RedirectError()
    {
        Response.Write("<script type=\"text/javascript\">parent.showAlertMessage('err','" + Resources.ErrorMsg.error_InvalidRequest + "',1);</script>");
    }

    protected void WriteResult(string message, int code)
    {
        Response.Write("<script type=\"text/javascript\">parent.showAlertMessage('err','" + message + "'," + code + "); parent.afterUpdate(true, 2000); </script>");
    }

    protected void UpdateData()
    {
        try
        {
            var custId = int.Parse(Request["custId"].ToString());

            var autoTransferStatus = autoTransferDataAccess.GetAutoTransferJobStatus(custId);
            if (autoTransferStatus)
            {
                WriteResult(Customer_Labels.ConditionChangeFailed_AutoJobRunning, 1);
                return;
            }

            var rs = UpdateCondition();
            if (rs.ErrorCode != 0)
            {
                ResponseError(rs);
                return;
            }

            if (!rs.AffectedDownlinesInfo.Any())
            {
                WriteResult("Update transfer condition successfully.", 0);
                return;
            }

            var userId = int.Parse(Session["AccId"].ToString());

            foreach (var row in rs.AffectedDownlinesInfo)
            {
                var uplineId = row.CustId;

                var toastMessageCriteria = new InsertToastMessageCriteria(
                    ToastMessageTypeConstants.Warning,
                    ToastMessageSiteFunctionIdConstants.ConditionChange,
                    uplineId,
                    userId,
                    new ToastContentModel(Customer_Labels.ResourceManager, "TransferConditionChange", "en"),
                    new ToastContentModel(Customer_Labels.ResourceManager, "TransferConditionChange", "ch"),
                    new ToastContentModel(Customer_Labels.ResourceManager, "TransferConditionChange", "cs"),
                    new ToastContentModel(Customer_Labels.ResourceManager, "TransferConditionChange", "th"),
                    new ToastContentModel(Customer_Labels.ResourceManager, "TransferConditionChange", "vn"));

                autoTransferDataAccess.InsertToastMessage(toastMessageCriteria);

                var uplineName = row.Name;
                var dowlines = row.Downlines;
                var personalMessageCriteria = new InsertPersonalMessageCriteria(
                    string.Format(Customer_Labels.TransferConditionChange_PersonalMessage_en, dowlines),
                    string.Format(Customer_Labels.TransferConditionChange_PersonalMessage_ch, dowlines),
                    string.Format(Customer_Labels.TransferConditionChange_PersonalMessage_cs, dowlines),
                    string.Format(Customer_Labels.TransferConditionChange_PersonalMessage_th, dowlines),
                    string.Format(Customer_Labels.TransferConditionChange_PersonalMessage_vn, dowlines));

                var messageId = autoTransferDataAccess.InsertPersonalMessage(personalMessageCriteria);
                if (messageId > 0)
                {
                    autoTransferDataAccess.AssignPersonalMessage(messageId, uplineId, uplineName);
                }
            }

            WriteResult("Update transfer condition successfully.", 0);
        }
        catch (Exception ex)
        {
            LogExtensions.ExceptionHandler(ex);
        }
    }

    private UpdateTransferOptionResult UpdateCondition()
    {
        Hashtable param = new Hashtable();
        param.Add("custid", Request["custId"]);
        param.Add("userid", Session["AccId"]);

        string strUpdTranfer = "";

        if (Request["tranfer"].ToString() == "daily")
        {
            strUpdTranfer = "00000000";
        }
        else
        {
            if (Request["chkSun"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            if (Request["chkMon"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            if (Request["chkTue"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            if (Request["chkWed"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            if (Request["chkThurs"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            if (Request["chkFri"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            if (Request["chkSat"] != null)
            {
                strUpdTranfer += "1";
            }
            else
            {
                strUpdTranfer += "0";
            }
            strUpdTranfer += "1";
        }

        param.Add("transferoption", strUpdTranfer);
        param.Add("turnoffautotransfer", Request["rad-change-affect"].ToString() == "1");

        param.Add("subaccid", 0);
        param.Add("language", "E");
        param.Add("errcode", 0);
        param.Add("errmsg", "");
        param.Add("returnerrcode", 1);
        // update missing IP
        var ipClient = Sunplus.Accounting.Core.Helper.Utils.GetClientIP();
        param.Add("ip", ipClient);

        var rs = customerSettingDataAccess.UpdateTransferOption(param);

        return rs;
    }

    private void ResponseError(UpdateTransferOptionResult rs)
    {
        if (rs.ErrorCode == 500)
        {
            //You are not authorized on this function
            WriteResult(rs.ErrorMessage, 1);
            return;
        }

        Response.Write("<script type=\"text/javascript\">parent.showAlertMessage('err','" + rs.ErrorMessage + "',1); </script>");
    }
}